function prng(seed){var a=(seed>>>0)||1;return function(){a|=0;a=(a+0x6D2B79F5)|0;var t=Math.imul(a^(a>>>15),1|a);t=(t+Math.imul(t^(t>>>7),61|t))^t;return((t^(t>>>14))>>>0)/4294967296;};}
function demoRun(seed){var R=prng(seed*499979+23);var ms=[];var y=1990,c=1;for(var i=0;i<6;i++){y+=3+((R()*8)|0);c=c*(1.6+R()*1.2);ms.push({year:y,cap:+c.toFixed(2)});}var n=ms.length,sx=0,sy=0,sxx=0,sxy=0;ms.forEach(function(m){var ly=Math.log(m.cap);sx+=m.year;sy+=ly;sxx+=m.year*m.year;sxy+=m.year*ly;});var slope=(n*sxy-sx*sy)/(n*sxx-sx*sx);var icept=(sy-slope*sx)/n;var target=Math.log(ms[n-1].cap*2);var fy=Math.round((target-icept)/slope);return{milestones:ms,annual_growth_pct:+((Math.exp(slope)-1)*100).toFixed(1),doubling_forecast_year:fy};}
var SEED = 84501;
console.log(JSON.stringify(demoRun(SEED), null, 1));

